ALTER POLICY "Private quote image read" ON storage.objects USING(bucket_id='quote-photos' AND (storage.foldername(name))[1]=public.current_company_id()::text AND public.member_commercial_can('estimates'));
ALTER POLICY "Private quote image insert" ON storage.objects WITH CHECK(bucket_id='quote-photos' AND (storage.foldername(name))[1]=public.current_company_id()::text AND name ~ '^[a-f0-9-]{36}/[a-f0-9-]{36}\.jpg$' AND public.member_commercial_can('estimates') AND public.company_module_access(public.current_company_id(),'core'));
ALTER POLICY "Unused private quote image delete" ON storage.objects USING(bucket_id='quote-photos' AND (storage.foldername(name))[1]=public.current_company_id()::text AND public.member_commercial_can('estimates') AND public.company_module_access(public.current_company_id(),'core') AND NOT EXISTS(SELECT 1 FROM public.customer_quote_photos p WHERE p.storage_path=name));
ALTER POLICY "Unused quote photo delete" ON public.customer_quote_photos USING(company_id=public.current_company_id() AND public.member_commercial_can('estimates') AND public.company_module_access(company_id,'core') AND NOT EXISTS(SELECT 1 FROM public.customer_quotes q WHERE q.company_id=customer_quote_photos.company_id AND (q.data->'photos' @> jsonb_build_array(jsonb_build_object('id',customer_quote_photos.id)) OR q.snapshot->'document'->'photos' @> jsonb_build_array(jsonb_build_object('id',customer_quote_photos.id)))));
CREATE POLICY commercial_contract_masters_read ON public.document_masters FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND kind IN ('contract','checklist') AND state='active' AND public.member_commercial_can('contracts'));
DO $$ DECLARE d text; BEGIN
SELECT pg_get_functiondef('public.customer_quote_action(uuid,text,jsonb)'::regprocedure) INTO d;
d:=replace(d,'day=nullif(_data->>''scheduled_date'','''')::date;','day=nullif(_data->>''scheduled_date'','''')::date; IF day IS NULL AND (nullif(_data->>''window_start'','''') IS NOT NULL OR nullif(_data->>''window_end'','''') IS NOT NULL) THEN RAISE EXCEPTION ''Unscheduled visits cannot have time windows''; END IF;'); EXECUTE d;
END $$;